export type Route = { path: string[]; query: URLSearchParams };

// Segments are not percent-decoded: ids are generated by us and never need it.
export function parseHash(hash: string): Route {
  const rest = hash.replace(/^#\/?/, '');
  const q = rest.indexOf('?');
  const path = (q < 0 ? rest : rest.slice(0, q)).split('/').filter(Boolean);
  return { path, query: new URLSearchParams(q < 0 ? '' : rest.slice(q + 1)) };
}

const hasWindow = typeof window !== 'undefined'; // node tests import parseHash

export const router: Route = $state(parseHash(hasWindow ? location.hash : ''));

if (hasWindow) {
  window.addEventListener('hashchange', () => {
    const r = parseHash(location.hash);
    router.path = r.path;
    router.query = r.query;
  });
}

export function navigate(path: string): void {
  location.hash = '#/' + path;
}
